/* Lot 117: font-size with hundredths and font-relative units (generated by scripts/lot117_gen.py; expectations from scripts/lot117_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "webeng.h"

static we_doc_t g_doc;
static we_forms_t g_forms;

static void lay(const char *html) {
    we_forms_init(&g_forms);
    we_set_forms(&g_doc, &g_forms);
    TEST_ASSERT_EQUAL(0, we_parse(&g_doc, html, (int)strlen(html)));
    TEST_ASSERT_EQUAL(0, we_style(&g_doc));
    TEST_ASSERT_EQUAL(0, we_layout_viewport(&g_doc, 640, 480));
}

static we_node_t g_none;

/* the element with this id (a blank node with h -1 when none) */
static const we_node_t *el(const char *id) {
    int i = we_find_id(&g_doc, id);
    g_none.h = -1;
    return i >= 0 ? &g_doc.nodes[i] : &g_none;
}

static int diag_has(const char *t) {
    uint32_t i;
    for (i = 0; i < g_doc.ndiag; i++) if (strstr(g_doc.diag[i], t)) return 1;
    return 0;
}

/* font_px, font100 and the line_height, lh_unitless, lh_frac fields */
static void font_lh(const char *id, int px, int f100, int lh, int unitless, int frac) {
    TEST_ASSERT_EQUAL(px, el(id)->font_px);
    TEST_ASSERT_EQUAL(f100, el(id)->font100);
    TEST_ASSERT_EQUAL(lh, el(id)->line_height);
    TEST_ASSERT_EQUAL(unitless, el(id)->lh_unitless);
    TEST_ASSERT_EQUAL(frac, el(id)->lh_frac);
}

static int text_y(const char *t) {
    uint32_t i;
    for (i = 0; i < g_doc.nitems; i++)
        if (g_doc.items[i].kind == OS_FB_WEB_TEXT && !strcmp(g_doc.items[i].text, t)) return g_doc.items[i].y;
    return -1000;
}

static we_unit_ctx_t c;
static int out;

